import{_ as d,o as r,c as o,a4 as a}from"./chunks/framework.vNSRaLQv.js";const c=JSON.parse('{"title":"Spring Cloud vs 云原生：两种架构对比","description":"","frontmatter":{"title":"Spring Cloud vs 云原生：两种架构对比","date":"2026-08-05T00:00:00.000Z"},"headers":[],"relativePath":"posts/12-springcloud-vs-cloudnative.md","filePath":"posts/12-springcloud-vs-cloudnative.md"}'),e={name:"posts/12-springcloud-vs-cloudnative.md"};function n(s,t,i,h,l,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="spring-cloud-vs-云原生-两种架构对比" tabindex="-1">Spring Cloud vs 云原生：两种架构对比 <a class="header-anchor" href="#spring-cloud-vs-云原生-两种架构对比" aria-label="Permalink to &quot;Spring Cloud vs 云原生：两种架构对比&quot;">​</a></h1><h2 id="_1-核心差异" tabindex="-1">1. 核心差异 <a class="header-anchor" href="#_1-核心差异" aria-label="Permalink to &quot;1. 核心差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Spring Cloud 模式</th><th>云原生模式</th></tr></thead><tbody><tr><td><strong>网关职责</strong></td><td>网关大包大揽：路由 + JWT + 授权 + 身份透传</td><td>网关只做入口安全：路由 + JWT 验签 + 限流</td></tr><tr><td><strong>授权位置</strong></td><td>网关统一授权（GatewayAuthorizationManager）</td><td>各服务自行授权（从 JWT 取身份，自己判断）</td></tr><tr><td><strong>服务间通信</strong></td><td>Feign（HTTP/1.1 + JSON）</td><td>gRPC（HTTP/2 + Protobuf）</td></tr><tr><td><strong>服务发现</strong></td><td>Nacos（Java，几百 MB）</td><td>etcd（Go，几十 MB，K8s 标准）</td></tr><tr><td><strong>消息队列</strong></td><td>RocketMQ（Java，几百 MB）</td><td>NATS（Go，~20MB，CNCF 标准）</td></tr><tr><td><strong>部署方式</strong></td><td>JAR + JVM（~300MB）</td><td>原生二进制（~15MB）</td></tr><tr><td><strong>可观测性</strong></td><td>Spring Actuator + 自建</td><td>Prometheus + Loki + OpenTelemetry（CNCF 标准）</td></tr><tr><td><strong>安全模型</strong></td><td>边界信任（内网安全）</td><td>零信任（每次请求都验证）</td></tr></tbody></table><h2 id="_2-两种模式没有绝对好坏-取决于场景" tabindex="-1">2. 两种模式没有绝对好坏，取决于场景 <a class="header-anchor" href="#_2-两种模式没有绝对好坏-取决于场景" aria-label="Permalink to &quot;2. 两种模式没有绝对好坏，取决于场景&quot;">​</a></h2><h3 id="什么时候-spring-cloud-好" tabindex="-1">什么时候 Spring Cloud 好？ <a class="header-anchor" href="#什么时候-spring-cloud-好" aria-label="Permalink to &quot;什么时候 Spring Cloud 好？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>原因</th></tr></thead><tbody><tr><td><strong>团队全是 Java 工程师</strong></td><td>零学习成本，Spring 生态成熟</td></tr><tr><td><strong>大公司，已有完善基础设施</strong></td><td>服务器管够，不在乎几百 MB 内存</td></tr><tr><td><strong>业务复杂，需要快速迭代</strong></td><td>Spring Cloud Gateway + Spring Security 开箱即用</td></tr><tr><td><strong>不需要弱设备</strong></td><td>只在云服务器上跑</td></tr></tbody></table><h3 id="什么时候云原生好" tabindex="-1">什么时候云原生好？ <a class="header-anchor" href="#什么时候云原生好" aria-label="Permalink to &quot;什么时候云原生好？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>原因</th></tr></thead><tbody><tr><td><strong>盒子/弱设备部署</strong></td><td>Go 二进制 ~15MB，内存 1GB 够用</td></tr><tr><td><strong>多语言团队（Go + Java）</strong></td><td>gRPC 跨语言，各自独立</td></tr><tr><td><strong>追求资源利用率</strong></td><td>内存从 2GB+ 降到 600MB</td></tr><tr><td><strong>面试/简历需要</strong></td><td>CNCF 标准，面试官认可</td></tr></tbody></table><h2 id="_3-为什么你的场景不适合-spring-cloud" tabindex="-1">3. 为什么你的场景不适合 Spring Cloud <a class="header-anchor" href="#_3-为什么你的场景不适合-spring-cloud" aria-label="Permalink to &quot;3. 为什么你的场景不适合 Spring Cloud&quot;">​</a></h2><p>你当前 Spring Cloud 的架构放在云服务器上完全没问题，问题在于<strong>你要跑盒子</strong>：</p><table tabindex="0"><thead><tr><th>组件</th><th>内存</th><th>盒子 1GB 能跑？</th></tr></thead><tbody><tr><td>Nacos</td><td>~300MB</td><td>❌</td></tr><tr><td>RocketMQ</td><td>~300MB</td><td>❌</td></tr><tr><td>ES</td><td>~500MB</td><td>❌</td></tr><tr><td>网关（JVM）</td><td>~200MB</td><td>❌</td></tr><tr><td>每个 Java 服务</td><td>~200MB</td><td>❌</td></tr><tr><td><strong>合计</strong></td><td><strong>2GB+</strong></td><td><strong>❌</strong></td></tr></tbody></table><p>换成云原生后：</p><table tabindex="0"><thead><tr><th>组件</th><th>内存</th><th>盒子 1GB 能跑？</th></tr></thead><tbody><tr><td>etcd</td><td>~50MB</td><td>✅</td></tr><tr><td>NATS</td><td>~20MB</td><td>✅</td></tr><tr><td>Redis</td><td>~100MB</td><td>✅</td></tr><tr><td>Traefik</td><td>~30MB</td><td>✅</td></tr><tr><td>每个 Go 服务</td><td>~15MB</td><td>✅</td></tr><tr><td>业务合计</td><td>~230MB</td><td>✅</td></tr></tbody></table><h2 id="_4-结论" tabindex="-1">4. 结论 <a class="header-anchor" href="#_4-结论" aria-label="Permalink to &quot;4. 结论&quot;">​</a></h2><p><strong>Spring Cloud 没有错，只是不适合你的场景。</strong></p><p>你现在做的事就是从&quot;一个正确的架构&quot;迁移到&quot;另一个正确的架构&quot;，因为你的部署目标变了（从云服务器变成了盒子设备）。</p>',16)])])}const p=d(e,[["render",n]]);export{c as __pageData,p as default};
